from pathlib import Path
import json,copy
ROOT=Path(__file__).resolve().parent
pages=[{'id':'cover','cover':True}]
SEC=''
def P(t):return {'type':'p','text':t}
def H(t):return {'type':'h','text':t}
def S(t):return {'type':'small','text':t}
def D(kind,height=160,**kw):return dict(type='diagram',kind=kind,height=height,**kw)
def N(p='B4',d=1,**kw):return dict(pitch=p,dur=d,**kw)
def R(d):return dict(rest=True,dur=d)
def row(title,notes=None,d=1,**kw):return dict(title=title,events=[N(n,d) for n in notes] if notes else [],**kw)
def SC(*rows,rh=120):return D('score',len(rows)*rh,rows=list(rows),rowHeight=rh)
def pg(id,title,*blocks):pages.append(dict(id=id,title=title,section=SEC,blocks=list(blocks)))
def exercise(text):return [H('Ejercicios'),P(text)]
C=['C4','D4','E4','F4','G4','A4','B4','C5']
SEC='Presentación'
pg('prologo','Solfeo Aplicado: lectura y comprensión del lenguaje musical',
P('Latin Music Mastery presenta un método de formación musical que integra lectura, escritura, audición, entonación y análisis. La notación musical representa gráficamente sonidos, silencios y sus relaciones; su lectura permite comprenderlos, incluso sin ejecutarlos.'),
P('El Diccionario de la lengua española define <b>solfeo</b> como «Adiestramiento para leer y entonar la notación musical». Este método desarrolla esa práctica junto con el estudio de los elementos que organizan el lenguaje musical. [1]'),
P('La formación es común a todas las especialidades. Comprender alturas, intervalos, ritmos, escalas y claves forma parte de la preparación de un músico profesional. La voz permite nombrar las notas, practicar el ritmo y desarrollar la afinación; estas habilidades se trabajan progresivamente, sin exigir formación vocal previa. La audición interior permite imaginar los sonidos sin emitirlos.'),
P('La tradición académica aporta conceptos y convenciones de escritura. Su aplicación se desarrolla mediante explicaciones, ejemplos en pentagramas y ejercicios de dificultad gradual.'),
H('Nuestra meta'),P('Formar músicos profesionales capaces de comprender, leer, escribir y analizar notación musical con precisión, desde sus elementos fundamentales hasta estructuras de mayor complejidad, y aplicar estos conocimientos a la interpretación musical, independientemente de su especialidad instrumental.'))
pg('metodo','Aprendizaje progresivo: de lo simple a lo complejo',
P('Cada contenido se presenta mediante una explicación y un ejemplo. Las actividades de reconocimiento, lectura, escritura y entonación permiten trabajar sus diferentes aspectos.'),
H('Lectura y escritura'),P('<b>Leer y comprender:</b> examinar un fragmento e identificar las notas, figuras, silencios e indicaciones estudiadas. Leer no exige siempre cantar o percutir. La ejecución se indica expresamente en cada ejercicio.<br/><b>Escribir:</b> representar gráficamente sonidos y silencios mediante la notación musical.'),
H('Progresión en espiral'),P('Los contenidos se retoman y amplían a medida que el estudiante avanza. Por ejemplo, una figura musical se presenta primero con su duración; después se utiliza en un compás, se combina con silencios y se integra en una melodía. Las nuevas dificultades se incorporan gradualmente, apoyándose en lo aprendido.'),
H('Práctica y evaluación'),P('La práctica se organiza mediante ejercicios progresivos con objetivos definidos. El estudiante ejercita la identificación de los signos musicales, la comprensión de sus relaciones y la precisión en la lectura, la escritura y la entonación. Cada ejercicio permite comprobar lo aprendido, identificar errores y corregirlos antes de incorporar nuevas dificultades.'),P('La evaluación considera por separado la comprensión teórica, la precisión rítmica, la afinación y el uso correcto de la notación, según el contenido trabajado. El progreso se demuestra al resolver correctamente los ejercicios y aplicar lo aprendido en ejemplos nuevos.'))
SEC='Módulo 1 · Elementos de la notación musical'
pg('nomenclatura','1.1 · Origen y nombres de las notas',P('En la Europa medieval, la enseñanza del canto necesitaba recursos que permitieran recordar y comunicar melodías. La escritura sobre líneas hizo más precisa la representación de las alturas. En la Italia del siglo XI, Guido de Arezzo desarrolló procedimientos para relacionar sonidos, posiciones escritas y sílabas. [2]'),P('Las sílabas <b>ut, re, mi, fa, sol, la</b> proceden de los comienzos de seis frases del himno Ut queant laxis. Si se incorporó después a partir de Sancte Iohannes. Do se difundió como sustituto de ut desde el siglo XVII. El pentagrama y la escritura de las duraciones resultaron de un desarrollo de varios siglos.'),H('Nombres actuales'),P('<b>Do · Re · Mi · Fa · Sol · La · Si</b><br/>Después de si vuelve do en otro registro. En el sistema internacional de letras: <b>C · D · E · F · G · A · B</b>.'),P('Una nota identifica una altura; una figura indica una duración relativa. Una misma altura puede escribirse con distintas figuras. Un silencio indica una duración sin sonido de la voz o parte a la que pertenece.'),*exercise('1. Recita los nombres desde do hasta el siguiente do y regresa.<br/>2. Continúa la serie desde fa durante ocho nombres.<br/>3. Escribe las letras correspondientes a re, sol, la y si.'))
pg('figuras','1.2 · Figuras musicales y silencios',P('La redonda es la referencia de estas proporciones. Cada figura de la tabla dura la mitad de la anterior. El silencio correspondiente tiene el mismo valor. La tabla presenta el sistema completo; los primeros ejercicios emplean solo redondas, blancas y negras.'),D('values',475),S('El silencio de redonda cuelga de una línea; el de blanca se apoya sobre ella. El silencio de compás completo puede usar el signo de redonda, aunque el compás no dure cuatro negras.'))
pg('relaciones','1.3 · Relaciones de duración',P('Una redonda equivale a dos blancas; cada blanca, a dos negras. Cada rama del diagrama divide una duración en dos partes iguales. El número de figuras aumenta, pero la duración total de cada fila permanece igual.'),D('pyramid',365),P('<b>1 redonda = 2 blancas = 4 negras = 8 corcheas = 16 semicorcheas = 32 fusas = 64 semifusas = 128 garrapateas = 256 semigarrapateas.</b>'),*exercise('1. ¿Cuántas corcheas equivalen a una blanca?<br/>2. ¿Cuántas semifusas equivalen a una negra?<br/>3. Expresa media redonda mediante dos figuras iguales.'))
pg('partes','1.4 · Cabeza, plica, corchete y barra',P('La <b>cabeza</b> ocupa una línea o un espacio e indica la altura. Puede ser hueca o llena. La <b>plica</b> es el trazo vertical. El <b>corchete</b> se añade a partir de la corchea; cada corchete adicional divide el valor por dos. Las <b>barras de unión</b> sustituyen a los corchetes cuando las notas se agrupan.'),SC(row('Cabeza hueca sin plica: redonda',['G4'],1),row('Cabeza hueca con plica: blanca',['G4'],2),row('Cabeza llena: negra, corchea, semicorchea',None,events=[])) if False else SC(dict(title='Redonda · blanca · negra · corchea · semicorchea',events=[N('G4',d) for d in [1,2,4,8,16]])),P('En una sola voz, las notas situadas debajo de la línea central suelen llevar plica hacia arriba, a la derecha de la cabeza; desde la línea central suelen llevarla hacia abajo, a la izquierda. La dirección facilita la lectura y no cambia la altura ni la duración.'),SC(dict(title='Dirección de las plicas en una sola voz',events=[N(n,4) for n in ['E4','G4','B4','D5','F5']])),*exercise('Dibuja una blanca, una negra y una corchea sobre una misma posición. Señala qué parte cambia y qué información permanece igual.'))
pg('pentagrama','1.5 · Pentagrama, líneas y espacios',P('El <b>pentagrama</b> está formado por cinco líneas paralelas y cuatro espacios. Se cuentan desde abajo: primera línea, segundo espacio, etc. La cabeza de una nota queda centrada sobre una línea o dentro de un espacio.'),D('staffmap',165),P('Las <b>líneas adicionales</b> prolongan el sistema por encima o por debajo. Se dibujan solo junto a la nota que las necesita. Una clave permite asignar nombres a estas posiciones.'),SC(row('Posiciones consecutivas: línea, espacio, línea…',C,1)),*exercise('1. Dibuja un pentagrama y numera sus líneas y espacios en el lugar correspondiente.<br/>2. Coloca cabezas de redonda en la primera línea, el tercer espacio y la quinta línea. Todavía no es necesario asignarles nombres.'))
pg('sol','1.6 · Clave de Sol y ubicación de las notas',P('La clave de Sol en segunda línea fija <b>sol4</b> en esa línea. El signo rodea la línea que identifica. Desde ese sol, cada posición consecutiva asciende o desciende un nombre. En este manual, do4 es el do central.'),SC(row('Líneas: Mi · Sol · Si · Re · Fa',['E4','G4','B4','D5','F5'],1),row('Espacios: Fa · La · Do · Mi',['F4','A4','C5','E5'],1),row('Do central a Do agudo',C,1)),P('El do4 se escribe en la primera línea adicional inferior. Re4 ocupa el espacio inmediatamente debajo del pentagrama. Las redondas de estos mapas muestran posiciones: no constituyen todavía una melodía medida.'),*exercise('Copia las tres series. Cubre los nombres y lee de izquierda a derecha; después, en sentido inverso.'))
SEC='Módulo 2 · Pulso, compás y lectura inicial'
pg('pulso','2.1 · Pulso, ritmo y tempo',P('El <b>pulso</b> es la referencia periódica que permite organizar el tiempo musical. El <b>ritmo</b> resulta de la sucesión y relación de duraciones, silencios y acentos. El <b>tempo</b> indica la velocidad del pulso.'),P('BPM significa pulsaciones por minuto. La indicación <b>negra = 60</b> asigna un segundo a cada negra. Negra = 120 asigna medio segundo. Debe indicarse la figura de referencia: un mismo número de BPM no produce la misma duración si el pulso es una blanca o una negra.'),SC(dict(title='Negra = 60: cuatro pulsos regulares',events=[N('G4',4,label=str(i)) for i in range(1,5)],tempo='Negra = 60'),dict(title='Duraciones diferentes sobre la misma referencia',events=[N('G4',2,label='2 pulsos'),N('G4',4,label='1 pulso'),R(4)])),P('Si la negra recibe el pulso, su duración en milisegundos es <b>60 000 ÷ BPM</b>. La corchea dura la mitad; la blanca, el doble. La intensidad no cambia el valor de una figura.'),*exercise('Marca cuatro pulsos regulares. En la segunda serie, sostén el primer sonido durante dos pulsos, emite el siguiente en el tercero y guarda silencio en el cuarto.'))
pg('compas','2.2 · Cifra de compás y líneas divisorias',P('El <b>compás</b> organiza los pulsos en grupos. Una línea divisoria separa un compás del siguiente. La cifra inicial establece su capacidad mediante dos números superpuestos: numerador y denominador.'),P('En <b>4/4</b>, el denominador 4 representa la negra y el numerador 4 indica una capacidad de cuatro negras. No exige cuatro ataques: pueden escribirse una redonda, dos blancas u otras combinaciones equivalentes.'),SC(dict(title='Tres compases de igual capacidad',meter='4/4',bars=[[N('C4',1)],[N('D4',2),N('E4',2)],[N('F4',2),N('G4',4),N('A4',4)]])),P('Los denominadores representan fracciones de redonda: <b>1 = redonda, 2 = blanca, 4 = negra, 8 = corchea, 16 = semicorchea</b>. La suma de notas y silencios debe completar la capacidad indicada, salvo casos específicos como la anacrusa.'),*exercise('1. Suma los valores de cada compás del ejemplo.<br/>2. Escribe tres combinaciones diferentes que completen 4/4.<br/>3. Explica por qué ocho corcheas caben en un compás de 4/4.'))
pg('unidades','2.3 · Unidad de compás, tiempo y subdivisión',P('La <b>unidad de compás</b> equivale a la duración total de un compás. La <b>unidad de tiempo</b> equivale a un pulso. La <b>unidad de subdivisión</b> equivale a una de las partes iguales en que se divide ese pulso.'),SC(dict(title='4/4: compás = redonda; tiempo = negra; subdivisión = corchea',events=[N('B4',1,label='compás'),N('B4',4,label='tiempo'),N('B4',8,label='subdivisión')]),dict(title='2/4: compás = blanca; tiempo = negra; subdivisión = corchea',events=[N('B4',2,label='compás'),N('B4',4,label='tiempo'),N('B4',8,label='subdivisión')]),dict(title='3/4: compás = blanca con puntillo; tiempo = negra',events=[N('B4',2,dot=True,label='compás'),N('B4',4,label='tiempo'),N('B4',8,label='subdivisión')])),P('El puntillo añade la mitad del valor de la figura: la blanca con puntillo equivale a tres negras. En los compases simples, el pulso se divide en dos partes iguales. En los compuestos, se divide en tres; por ello el denominador no identifica siempre la unidad de tiempo.'))
pg('redondas','2.4 · Lectura de redondas en 4/4',P('Cada redonda ocupa un compás completo de 4/4. Reconoce primero la posición y el nombre de cada nota; después, cuenta cuatro pulsos por compás. Para entonar, escucha una referencia de do4 y conserva cada sonido hasta el siguiente compás.'),SC(dict(title='Ejercicio 1 · Movimiento ascendente',meter='4/4',bars=[[N(n)] for n in C[:4]]),dict(title='Ejercicio 2 · Continuación y regreso',meter='4/4',bars=[[N(n)] for n in ['G4','F4','E4','D4']]),dict(title='Ejercicio 3 · Reconocimiento sin nombres escritos',meter='4/4',bars=[[N(n)] for n in ['E4','F4','D4','C4']])),*exercise('1. Nombra las notas sin cantarlas.<br/>2. Entona las tres líneas con una referencia inicial.<br/>3. Escribe cuatro redondas que asciendan desde sol4.'))
pg('combinaciones','2.5 · Blancas, negras y silencios',P('En 4/4, una blanca ocupa dos pulsos y una negra, uno. Los silencios mantienen el transcurso del compás: el pulso continúa aunque no se produzca sonido.'),SC(dict(title='Ejercicio 4 · Dos blancas por compás',meter='4/4',bars=[[N('C4',2),N('D4',2)],[N('E4',2),N('D4',2)],[N('C4',1)]]),dict(title='Ejercicio 5 · Blanca y negras',meter='4/4',bars=[[N('C4',2),N('D4',4),N('E4',4)],[N('F4',4),N('E4',4),N('D4',2)],[N('C4',1)]]),dict(title='Ejercicio 6 · Sonidos y silencios',meter='4/4',bars=[[N('G4',4),R(4),N('G4',2)],[R(2),N('F4',4),N('E4',4)],[N('D4',2),R(2)]])),*exercise('Percute primero el ritmo de cada línea sobre una sola altura. Después nombra las notas con sus duraciones y, finalmente, entónalas. Mantén los silencios completos.'))
for count,name,directions in [(2,'binario','abajo y arriba'),(3,'ternario','abajo, derecha y arriba'),(4,'cuaternario','abajo, izquierda, derecha y arriba')]:
 pg(f'marcar-{count}',f'2.{count+4} · Marcación del compás de {count}/4',P(f'El compás de {count}/4 contiene {count} pulsos de negra. Su organización es {name}. La mano derecha marca los tiempos mediante un recorrido de {count} movimientos: <b>{directions}</b>.'),D('conduct',270,count=count),P('El primer tiempo coincide con el gesto descendente: <b>downbeat</b>. El último movimiento prepara el regreso al primer tiempo. Los puntos numerados representan la llegada de cada gesto, no una pausa. El dibujo simplifica la trayectoria; el movimiento real es continuo.'),SC(dict(title='Cuenta un número por cada negra',meter=f'{count}/4',bars=[[N('G4',4,label=str(i+1)) for i in range(count)]]),rh=110),P('En 4/4, el tercer tiempo tiene un apoyo secundario; el primero conserva la referencia principal.' if count==4 else 'El primer tiempo tiene mayor jerarquía métrica. Esta organización no obliga a tocar siempre más fuerte cada primer tiempo.'))
pg('completar','2.9 · Escritura y equivalencias métricas',P('Completa cada compás de 4/4 con la duración que falta. Puedes combinar notas y silencios. Escribe las respuestas en los pentagramas y comprueba la suma antes de ejecutarlas.'),P('<b>A.</b> Una blanca y una negra: añade una figura.<br/><b>B.</b> Tres negras: añade un silencio.<br/><b>C.</b> Una blanca: añade dos figuras iguales.<br/><b>D.</b> Un silencio de blanca: completa el compás con negras.'),D('blank',190,count=2),H('Lectura y entonación'),SC(dict(title='Ejercicio 7 · Figuras combinadas',meter='4/4',bars=[[N('C4',2),N('E4',4),N('D4',4)],[N('C4',4),N('D4',4),N('E4',2)],[N('D4',2),N('C4',2)]])),S('Respuestas posibles: A, negra; B, silencio de negra; C, dos negras; D, dos negras.'))
SEC='Módulo 3 · Alturas, tonos e intervalos'
pg('tonos','3.1 · Tono y semitono',P('El <b>semitono</b> es la menor distancia entre dos teclas contiguas del teclado cromático, incluidas las negras. Un <b>tono</b> equivale a dos semitonos. Entre mi-fa y si-do naturales hay un semitono; entre los demás vecinos naturales de la escala de do hay un tono.'),SC(row('Do mayor: tonos y semitonos',C,1,intervals=['T','T','S','T','T','T','S']),rh=130),P('El corchete señala un tono (T); el arco señala un semitono (S). La sucesión de alturas no tiene distancias iguales aunque las posiciones gráficas avancen de una en una.'),D('stair',205),*exercise('Entona do-re-mi-fa y regresa. Compara la distancia mi-fa con re-mi. Señala los dos semitonos de la escala sin confundir altura con intensidad.'))
pg('alteraciones','3.2 · Alteraciones y equivalencia enarmónica',P('El <b>sostenido</b> eleva un semitono; el <b>bemol</b> desciende un semitono; el <b>becuadro</b> restablece la nota natural. El doble sostenido eleva dos semitonos y el doble bemol desciende dos. La alteración se escribe antes de la cabeza.'),SC(row('Do natural · Do sostenido · Do natural · Re bemol',['C4','C#4','C4','Db4'],1),row('Fa natural · Fa doble sostenido · Sol natural',['F4','F##4','G4'],1),row('Si natural · Si doble bemol · La natural',['B4','Bbb4','A4'],1)),P('En el temperamento igual, do sostenido y re bemol corresponden a la misma tecla, pero se escriben y cumplen funciones diferentes: son <b>enarmónicos</b>. Una alteración accidental rige normalmente para la misma nota y octava hasta la barra siguiente; una ligadura puede prolongar el sonido alterado al compás siguiente.'),S('Ejemplos sin compás: las alteraciones muestran explícitamente cada cambio.'))
pg('intervalo','3.3 · Número y especie de los intervalos',P('Un <b>intervalo</b> es la distancia de altura entre dos sonidos. Su número se obtiene contando los nombres de ambas notas, incluidos los extremos: do-re es segunda; do-mi, tercera. La especie precisa su amplitud: mayor, menor, justa, aumentada o disminuida.'),SC(row('Segunda: Do-Re · Tercera: Do-Mi · Cuarta: Do-Fa',['C4','D4','C4','E4','C4','F4'],1),row('Quinta: Do-Sol · Sexta: Do-La · Séptima: Do-Si · Octava: Do-Do',['C4','G4','C4','A4','C4','B4','C4','C5'],1)),P('Segundas, terceras, sextas y séptimas pueden ser mayores o menores. Unísonos, cuartas, quintas y octavas se clasifican como justos en su forma de referencia. Ampliar un intervalo mayor o justo un semitono produce uno aumentado; reducir uno menor o justo un semitono produce uno disminuido.'),P('Un intervalo <b>melódico</b> presenta las notas sucesivamente; uno <b>armónico</b>, simultáneamente. Ascendente y descendente indican dirección, no especie.'),*exercise('Cuenta primero los nombres y después los semitonos: do-fa sostenido sigue siendo una cuarta; do-sol bemol, una quinta. Aunque ambas abarcan seis semitonos, su escritura es distinta.'))
interval_specs=[('Segundas',[('C4','Db4','menor · 1 semitono'),('C4','D4','mayor · 2 semitonos')],['C4','D4','E4','D4','C4']),('Terceras',[('C4','Eb4','menor · 3 semitonos'),('C4','E4','mayor · 4 semitonos')],['C4','D4','E4','C4','E4']),('Cuartas',[('C4','F4','justa · 5 semitonos'),('C4','F#4','aumentada · 6 semitonos')],['C4','D4','E4','F4','C4','F4']),('Quintas',[('C4','Gb4','disminuida · 6 semitonos'),('C4','G4','justa · 7 semitonos'),('C4','G#4','aumentada · 8 semitonos')],['C4','E4','G4','C4','G4']),('Sextas',[('C4','Ab4','menor · 8 semitonos'),('C4','A4','mayor · 9 semitonos')],['C4','E4','G4','A4','C4','A4']),('Séptimas y octavas',[('C4','Bb4','séptima menor · 10 semitonos'),('C4','B4','séptima mayor · 11 semitonos'),('C4','C5','octava justa · 12 semitonos')],['C4','E4','G4','B4','C5','C4'])]
for k,(name,pairs,prep) in enumerate(interval_specs):
 blocks=[P('Compara las distancias escritas desde do. Cuenta las posiciones y observa las alteraciones. En la preparación, las notas intermedias ayudan a anticipar la altura final; después omítelas y conserva el intervalo.')]
 blocks+=[SC(*[row(f'{name} · {desc}',[a,z],1) for a,z,desc in pairs],rh=103)]
 blocks+=[SC(row('Preparación y salto directo',prep,2),rh=107),P('Entona la preparación con una referencia inicial. Repite únicamente los extremos de cada intervalo y escribe un ejemplo descendente.')]
 if k==5:blocks+=[S('«Séptima de dominante» nombra un acorde sobre el V grado; no es una especie distinta de intervalo. En ese acorde, la séptima respecto de su fundamental es menor.')]
 pg('intervalos-'+str(k),f'3.{k+4} · {name}',*blocks)
SEC='Módulo 4 · Subdivisión y organización rítmica'
pg('corcheas','4.1 · Corcheas y semicorcheas',P('En un pulso de negra caben dos corcheas o cuatro semicorcheas. La subdivisión mantiene partes iguales dentro del pulso. Las barras de unión agrupan las notas según la organización del compás; equivalen a sus corchetes.'),SC(dict(title='Ejercicio 8 · Dos partes por pulso',meter='2/4',bars=[[N('G4',8) for _ in range(4)],[N('G4',4),N('A4',8),N('G4',8)]]),dict(title='Ejercicio 9 · Cuatro partes por pulso',meter='2/4',bars=[[N('G4',16) for _ in range(4)]+[N('G4',4)],[N('A4',8),N('G4',8),N('F4',4)]]),dict(title='Ejercicio 10 · Ritmo y dirección melódica',meter='2/4',bars=[[N('C4',8),N('D4',8),N('E4',4)],[N('F4',8),N('E4',8),N('D4',8),N('C4',8)]])),*exercise('Percute cada línea contando dos pulsos por compás. Después nombra las notas con el mismo ritmo y entona la tercera línea.'))
pg('puntillos','4.2 · Puntillo y ligadura de prolongación',P('El <b>puntillo</b> añade la mitad del valor original. Una negra con puntillo equivale a una negra más una corchea. El segundo puntillo añade la mitad del primero: una negra con doble puntillo equivale a siete semicorcheas.'),SC(dict(title='Negra con puntillo + corchea = dos negras',meter='2/4',bars=[[N('G4',4,dot=True),N('A4',8)]]),dict(title='Ligadura: dos notas de la misma altura, un solo ataque',meter='4/4',bars=[[N('G4',2),N('G4',2)]],slurs=[[0,1]])),P('La <b>ligadura de prolongación</b> une notas de la misma altura y suma sus duraciones sin repetir el ataque. Una ligadura entre alturas diferentes cumple otra función: articulación ligada o fraseo.'),*exercise('1. Completa 4/4 después de una blanca con puntillo.<br/>2. Escribe una duración de tres negras mediante dos figuras ligadas.<br/>3. Expresa una blanca con doble puntillo en corcheas.'),S('Respuestas: 1, una negra; 2, blanca ligada a negra de la misma altura; 3, siete corcheas.'))
pg('sincopa','4.3 · Síncopa, contratiempo y anacrusa',P('La <b>síncopa</b> comienza en una posición métricamente débil y se prolonga sobre otra más fuerte. El <b>contratiempo</b> presenta un ataque débil precedido por un silencio en la posición fuerte correspondiente. La <b>anacrusa</b> es un comienzo incompleto que conduce al primer compás pleno.'),SC(dict(title='Síncopa dentro de 4/4: corchea, negra, corchea, blanca',meter='4/4',bars=[[N('G4',8),N('G4',4),N('G4',8),N('G4',2)]]),dict(title='Contratiempo: silencio en cada comienzo de pulso',meter='2/4',bars=[[R(8),N('G4',8),R(8),N('G4',8)]]),dict(title='Anacrusa de una negra antes del compás completo',meter='4/4',bars=[[N('D4',4)],[N('E4',2),N('D4',4),N('C4',4)]],pickup=True)),P('La anacrusa no es un error de suma. En muchas piezas su duración se complementa con un último compás incompleto. Conserva la referencia del pulso durante los silencios y las prolongaciones.'))
pg('compuestos','4.4 · Compases simples y compuestos',P('Los compases <b>simples</b> dividen cada tiempo en dos partes iguales. Los <b>compuestos</b> lo dividen en tres. En la interpretación habitual de <b>6/8</b> hay dos tiempos de negra con puntillo; cada tiempo contiene tres corcheas. El 6 cuenta las corcheas del compás, no seis pulsos principales. [3]'),SC(dict(title='6/8: dos grupos de tres corcheas',meter='6/8',bars=[[N('G4',8,label=v) for v in ['1','y','a','2','y','a']]]),dict(title='6/8: unidad de compás, tiempo y subdivisión',events=[N('G4',2,dot=True,label='compás'),N('G4',4,dot=True,label='tiempo'),N('G4',8,label='subdivisión')]),dict(title='3/4: tres grupos de dos corcheas',meter='3/4',bars=[[N('G4',8,label=v) for v in ['1','y','2','y','3','y']]])),P('9/8 contiene normalmente tres tiempos de negra con puntillo; 12/8, cuatro. 3/4 y 6/8 tienen igual capacidad escrita de seis corcheas, pero distinta agrupación. El tempo y el contexto pueden modificar el nivel de pulso percibido.'))
pg('asimetricos','4.5 · Compases de agrupación desigual',P('En 5/4 y 7/4 se combinan grupos de distinta extensión. La cifra indica la capacidad, pero la partitura y sus acentos aclaran la agrupación. Un 5/4 puede organizarse 3+2 o 2+3; un 7/4, 2+2+3, 3+2+2 u otra distribución explícita.'),SC(dict(title='5/4 agrupado 3 + 2',meter='5/4',bars=[[N('G4',4,mark='accent' if i in [0,3] else None,label=str(i+1)) for i in range(5)]]),dict(title='7/4 agrupado 2 + 2 + 3',meter='7/4',bars=[[N('G4',4,mark='accent' if i in [0,2,4] else None,label=str(i+1)) for i in range(7)]])),*exercise('Marca primero cada pulso. Después señala los comienzos de grupo. Reescribe 5/4 como 2+3 sin cambiar su duración total. Describe qué cambia en la organización de los acentos.'))
for ix,groups in enumerate([[(2,3,'Dosillo'),(3,2,'Tresillo'),(4,3,'Cuatrosillo')],[(5,4,'Quintillo'),(6,4,'Seisillo'),(7,4,'Septillo')],[(8,6,'Octosillo'),(9,8,'Novesillo')]]):
 pg('irregulares-'+str(ix),f'4.{6+ix} · Grupos de valoración especial',P('Un grupo de valoración especial distribuye una duración en un número de partes diferente del habitual. En la relación <b>n:m</b>, n figuras ocupan el tiempo de m figuras del mismo tipo. El corchete delimita el grupo; en la escritura habitual puede aparecer solo n cuando el contexto aclara la relación.'),SC(*[dict(title=f'{name}: {n} corcheas en el tiempo de {m}',events=[N('G4',8) for _ in range(n)],tuplet=f'{n}:{m}') for n,m,name in groups],rh=115),P('Calcula primero la duración total y después divídela entre las notas del grupo. Un tresillo 3:2 de corcheas ocupa una negra. Un seisillo 6:4 de corcheas ocupa una blanca; la agrupación interna no debe confundirse automáticamente con dos tresillos.' if ix==1 else 'Percute el grupo manteniendo su duración total. Existen grupos mayores de siete notas: la relación escrita, el contexto y la agrupación determinan su valor.'))
SEC='Módulo 5 · Escalas, tonalidad y arpegios'
pg('escala','5.1 · Escala mayor y grados tonales',P('Una <b>escala</b> ordena sonidos de forma ascendente o descendente. La escala mayor tiene la estructura <b>T-T-S-T-T-T-S</b>. Do mayor es el modelo sin sostenidos ni bemoles. Los números romanos identifican sus grados.'),SC(row('Do mayor: I · II · III · IV · V · VI · VII · I',C,1,intervals=['T','T','S','T','T','T','S']),rh=132),P('<b>I, tónica:</b> centro de referencia. <b>II, supertónica; III, mediante; IV, subdominante; V, dominante; VI, submediante; VII, sensible</b> cuando está a un semitono de la tónica. En la menor natural, el VII grado está a un tono y se denomina subtónica.'),SC(row('Grados de referencia: I-IV-V-I',['C4','F4','G4','C5'],2)),*exercise('1. Entona do mayor y detente en cada grado.<br/>2. Canta do-mi-sol-do y regresa.<br/>3. Identifica los grados que forman los dos semitonos.'))
pg('armaduras','5.2 · Armaduras de clave',P('La <b>armadura</b> se escribe después de la clave y antes del compás. Sus alteraciones afectan las notas correspondientes en todas sus octavas hasta que otra armadura o una alteración accidental modifique el contexto.'),D('keys',265,rows=[dict(title='Un sostenido: Fa sostenido · Sol mayor / Mi menor',key=1,tonic='G4'),dict(title='Un bemol: Si bemol · Fa mayor / Re menor',key=-1,tonic='F4'),dict(title='Dos bemoles: Si, Mi · Si bemol mayor / Sol menor',key=-2,tonic='Bb4')]),P('<b>Sostenidos:</b> Fa-Do-Sol-Re-La-Mi-Si. El último sostenido queda un semitono debajo de la tónica mayor.<br/><b>Bemoles:</b> Si-Mi-La-Re-Sol-Do-Fa. Desde dos bemoles, el penúltimo da la tónica mayor. La excepción que se memoriza es un bemol: Fa mayor.'),P('Una armadura corresponde a una tonalidad mayor y a su relativa menor. La tónica, las cadencias y el contexto permiten distinguirlas; la armadura sola no basta.'))
pg('orden-sostenidos','5.3 · Orden de los sostenidos',P('Cada nueva armadura conserva los sostenidos anteriores y añade el siguiente en el orden Fa-Do-Sol-Re-La-Mi-Si. Repite la cadena completa y observa su ubicación gráfica.'),D('keys',440,rows=[dict(title=f'{k} sostenido'+('s' if k>1 else '')+' · '+name,key=k,tonic=t) for k,name,t in [(1,'Sol mayor','G4'),(2,'Re mayor','D4'),(3,'La mayor','A4'),(4,'Mi mayor','E4'),(5,'Si mayor','B4')]]),S('Continúa: seis sostenidos, Fa sostenido mayor; siete, Do sostenido mayor. Sus armaduras completas aparecen en el repertorio tonal del módulo 6.'))
pg('orden-bemoles','5.4 · Orden de los bemoles',P('El orden de los bemoles es el inverso del orden de los sostenidos: Si-Mi-La-Re-Sol-Do-Fa. En cada armadura, señala el penúltimo bemol y nombra la tonalidad mayor.'),D('keys',440,rows=[dict(title=f'{abs(k)} bemol'+('es' if abs(k)>1 else '')+' · '+name,key=k,tonic=t) for k,name,t in [(-1,'Fa mayor','F4'),(-2,'Si bemol mayor','Bb4'),(-3,'Mi bemol mayor','Eb4'),(-4,'La bemol mayor','Ab4'),(-5,'Re bemol mayor','Db4')]]),S('Continúa: seis bemoles, Sol bemol mayor; siete, Do bemol mayor. Un bemol no corresponde a Sol mayor: Sol mayor lleva Fa sostenido.'))
pg('menor','5.5 · Relativa menor: tres formas',P('La relativa menor comienza en el VI grado de la escala mayor y comparte su armadura. La menor es relativa de Do mayor. Sus formas natural, armónica y melódica son variantes de la escala menor.'),SC(row('La menor natural · T-S-T-T-S-T-T',['A3','B3','C4','D4','E4','F4','G4','A4'],1,intervals=['T','S','T','T','S','T','T']),row('La menor armónica · VII grado elevado',['A3','B3','C4','D4','E4','F4','G#4','A4'],1,intervals=['T','S','T','T','S','T+S','S']),row('La menor melódica ascendente · VI y VII elevados',['A3','B3','C4','D4','E4','F#4','G#4','A4'],1,intervals=['T','S','T','T','T','T','S']),rh=119),P('En la forma melódica clásica, al descender vuelven los grados VI y VII de la menor natural. Se eleva el VII para formar una sensible; elevar también el VI evita la segunda aumentada de la forma armónica. En el uso jazzístico, la escala melódica puede conservar la forma ascendente en ambas direcciones. [4]'))
pg('acordes','5.6 · Tríadas y arpegios de dominante',P('Un <b>acorde</b> reúne sonidos que se consideran una unidad armónica. El <b>arpegio</b> presenta sucesivamente las notas de ese acorde. La tríada mayor contiene fundamental, tercera mayor y quinta justa; la menor cambia la tercera mayor por menor.'),SC(row('Do mayor: I · Do-Mi-Sol-Do',['C4','E4','G4','C5'],2),row('La menor: i · La-Do-Mi-La',['A3','C4','E4','A4'],2),row('V7 de Do mayor: Sol-Si-Re-Fa',['G3','B3','D4','F4'],2),row('V7 de La menor: Mi-Sol sostenido-Si-Re',['E4','G#4','B4','D5'],2),rh=100),P('El acorde V7 se construye sobre la dominante: tríada mayor y séptima menor. En la tonalidad menor se eleva el VII grado de la escala para formar la tercera mayor del acorde de dominante.'))
# Tonal library: spell each scale diatonically, retaining enharmonic distinctions.
LET='CDEFGAB';PCS=[0,2,4,5,7,9,11]
def midi(n):return (int(n[-1])+1)*12+PCS[LET.index(n[0])]+n[1:-1].count('#')-n[1:-1].count('b')
def scale(tonic,steps):
    out=[];base=midi(tonic);di=int(tonic[-1])*7+LET.index(tonic[0])
    for i,v in enumerate(steps):
        oct,idx=divmod(di+i,7);diff=base+v-((oct+1)*12+PCS[idx]);assert abs(diff)<=2
        out.append(LET[idx]+('#'*diff if diff>=0 else 'b'*(-diff))+str(oct))
    return out
major=[0,2,4,5,7,9,11,12];natural=[0,2,3,5,7,8,10,12];harm=[0,2,3,5,7,8,11,12];mel=[0,2,3,5,7,9,11,12]
tonals=[(0,'Do','C4','La','A3'),(1,'Sol','G4','Mi','E4'),(-1,'Fa','F4','Re','D4'),(2,'Re','D4','Si','B3'),(-2,'Si bemol','Bb3','Sol','G3'),(3,'La','A3','Fa sostenido','F#3'),(-3,'Mi bemol','Eb4','Do','C4'),(4,'Mi','E4','Do sostenido','C#4'),(-4,'La bemol','Ab3','Fa','F3'),(5,'Si','B3','Sol sostenido','G#3'),(-5,'Re bemol','Db4','Si bemol','Bb3'),(6,'Fa sostenido','F#4','Re sostenido','D#4'),(-6,'Sol bemol','Gb4','Mi bemol','Eb4'),(7,'Do sostenido','C#4','La sostenido','A#3'),(-7,'Do bemol','Cb4','La bemol','Ab3')]
SEC='Módulo 6 · Lectura tonal progresiva'
pg('estudio-tonal','6.1 · Procedimiento de lectura tonal',P('El estudio comienza con Do mayor y La menor. Continúa alternando armaduras de sostenidos y bemoles: Sol/Mi, Fa/Re, Re/Si, Si bemol/Sol. Avanza después hacia armaduras de mayor complejidad.'),P('<b>1. Identifica</b> la armadura y las notas alteradas.<br/><b>2. Lee</b> la escala y localiza tonos y semitonos.<br/><b>3. Entona</b> la tónica y el arpegio de su acorde.<br/><b>4. Compara</b> la escala mayor con su relativa menor.<br/><b>5. Ejecuta</b> el ejercicio y escribe una variación que conserve su compás.'),P('Las escalas siguientes son mapas de alturas sin compás. Las redondas separadas facilitan observar cada posición; las líneas con cifra de compás sí constituyen ejercicios medidos. Los arpegios de V7 terminan en la séptima del acorde, no en una resolución.'),H('Patrones de las escalas'),P('<b>Mayor:</b> T-T-S-T-T-T-S.<br/><b>Menor natural:</b> T-S-T-T-S-T-T.<br/><b>Menor armónica:</b> T-S-T-T-S-(T+S)-S.<br/><b>Menor melódica ascendente:</b> T-S-T-T-T-T-S.<br/><b>Melódica descendente clásica:</b> forma natural en orden inverso.'),P('T+S equivale a tres semitonos y forma una segunda aumentada en la escala menor armónica. No es un tono.'))
for k,(f,name,t,miname,mt) in enumerate(tonals):
    ma=scale(t,major);mn=scale(mt,natural);ha=scale(mt,harm);me=scale(mt,mel)
    arp=[ma[i] for i in [0,2,4,7]];v=scale(ma[4],[0,4,7,10]) if False else [ma[4],ma[6],scale(t,major+[14,16,17])[8],scale(t,major+[14,16,17])[10]]
    # V7 spell degrees V,VII,II,IV across octaves using diatonic extension.
    ext=scale(t,major+[14,16,17]);v=[ext[i] for i in [4,6,8,10]]
    ex=[[N(ma[0],2),N(ma[1],4),N(ma[2],4)],[N(ma[3],4),N(ma[2],4),N(ma[1],2)],[N(ma[4],2),N(ma[6],4),N(ma[7],4)],[N(ma[0],1)]]
    pg(f'tonal-{k}-mayor',f'6.{k*2+2} · {name} mayor',P(f'Armadura: {abs(f)} '+(('sostenido' if f==1 else 'sostenidos') if f>0 else ('bemol' if f==-1 else 'bemoles') if f<0 else 'alteraciones')+f'. Relativa menor: {miname} menor. Identifica la tónica y conserva la estructura de la escala mayor.'),SC(row('Escala mayor · corchete T / arco S',ma,1,key=f,intervals=['T','T','S','T','T','T','S']),row('Arpegio de tónica · I',arp,2,key=f),row('Arpegio de séptima de dominante · V7',v,2,key=f),rh=115),SC(dict(title='Ejercicio tonal · LMM',key=f,meter='4/4',bars=ex),rh=118),S('Lee la escala en ambos sentidos. Entona el ejercicio. Escribe otro final que llegue a la tónica y complete cuatro tiempos.'))
    hext=scale(mt,harm+[14,15,17]);mv=[hext[i] for i in [4,6,8,10]]
    pg(f'tonal-{k}-menor',f'6.{k*2+3} · {miname} menor',P(f'Relativa de {name} mayor. La armadura permanece; las elevaciones del VI o VII se escriben como alteraciones accidentales.'),SC(row('Natural',mn,1,key=f,intervals=['T','S','T','T','S','T','T']),row('Armónica · VII elevado',ha,1,key=f,intervals=['T','S','T','T','S','T+S','S']),row('Melódica ascendente · VI y VII elevados',me,1,key=f,intervals=['T','S','T','T','T','T','S']),row('Melódica descendente clásica',list(reversed(mn)),1,key=f,intervals=['T','T','S','T','T','S','T']),rh=116),SC(row('Arpegios · i (primeras cuatro notas) / V7 (últimas cuatro)',[mn[i] for i in [0,2,4,7]]+mv,2,key=f),rh=96),S('Entona las tres formas y explica qué grados cambian. Canta el arpegio i y el V7; después resuelve su sensible hacia la tónica.'))
SEC='Módulo 7 · Cromatismo y consolidación'
pg('cromatica','7.1 · Escala cromática',P('La escala cromática reúne doce alturas por octava mediante semitonos consecutivos. La escritura depende de la función tonal. Como ejercicio inicial, el ascenso siguiente emplea sostenidos y el descenso, bemoles; esta práctica no sustituye las reglas de escritura de cada contexto.'),SC(row('Ascenso cromático desde Do',['C4','C#4','D4','D#4','E4','F4','F#4','G4','G#4','A4','A#4','B4','C5'],1),row('Descenso cromático hasta Do',['C5','B4','Bb4','A4','Ab4','G4','Gb4','F4','E4','Eb4','D4','Db4','C4'],1)),*exercise('1. Identifica las teclas equivalentes entre ambos recorridos.<br/>2. Entona lentamente un semitono ascendente y descendente desde cada nota natural.<br/>3. Escribe el ascenso cromático desde sol4 hasta sol5.'),P('Un cambio cromático conserva el nombre y modifica su alteración, como do-do sostenido. Un semitono diatónico cambia de nombre, como mi-fa.'))
pg('consolidacion','7.2 · Lectura y escritura integradas',P('Antes de ejecutar, identifica clave, armadura, compás, alteraciones y duraciones. Separa la comprobación de alturas de la comprobación rítmica; después reúne ambas.'),SC(dict(title='Ejercicio 11 · Sol mayor',key=1,meter='4/4',bars=[[N('G4',2),N('A4',4),N('B4',4)],[N('C5',4),N('B4',4),N('A4',2)],[N('F#4',2),N('G4',2)]]),dict(title='Ejercicio 12 · Re menor',key=-1,meter='3/4',bars=[[N('D4',4),N('F4',4),N('A4',4)],[N('G4',4),N('E4',4),N('C#4',4)],[N('D4',2),R(4)]])),*exercise('1. Nombra las notas y reconoce los intervalos consecutivos.<br/>2. Percute el ritmo y entona cada línea.<br/>3. Copia la primera línea conservando los valores y comienza en do4; ajusta las alturas para mantener la estructura interválica.<br/>4. Escribe una frase propia de cuatro compases en 3/4.'),D('blank',95,count=1))
SEC='Módulo 8 · Expresión y articulación'
pg('dinamica','8.1 · Dinámica y matices',P('La <b>dinámica</b> regula la intensidad del sonido. Los <b>matices</b> indican niveles relativos: ppp, pianississimo; pp, pianissimo; p, piano; mp, mezzo piano; mf, mezzo forte; f, forte; ff, fortissimo; fff, fortississimo. Su realización depende del contexto, no de una cantidad fija de decibelios. [5]'),SC(dict(title='Gradación de intensidad',events=[N('G4',4,dynamic=d) for d in ['ppp','pp','p','mp','mf','f','ff','fff']]),dict(title='Crescendo · aumento gradual de intensidad',events=[N(n,4) for n in ['C4','D4','E4','F4','G4']],hairpin='cresc'),dict(title='Diminuendo · disminución gradual de intensidad',events=[N(n,4) for n in ['G4','F4','E4','D4','C4']],hairpin='dim')),P('Los reguladores expresan cambios graduales. Cresc. y dim. pueden sustituir el signo gráfico. <b>Sfz</b> pide un refuerzo puntual; <b>fp</b>, un ataque fuerte seguido inmediatamente de piano. No indican cambios de altura.'))
pg('acentos','8.2 · Acentos e intensidad puntual',P('El <b>acento</b> destaca una nota respecto de su contexto. El signo &gt; indica énfasis; el marcato, representado por un ángulo vertical, pide una marcación más definida. Sforzando (sfz) refuerza el ataque. Su alcance depende del estilo y de la frase.'),SC(dict(title='Acento escrito',events=[N('G4',4,mark='accent'),N('A4',4),N('G4',2)]),dict(title='Marcato',events=[N('G4',4,mark='marcato'),N('E4',4),N('C4',2)]),dict(title='Sforzando y forte-piano',events=[N('G4',2,dynamic='sfz'),N('G4',2,dynamic='fp')])),P('El acento métrico pertenece a la organización del compás. Un acento escrito puede destacar un tiempo débil y modificar la sensación rítmica sin cambiar la cifra de compás.'),*exercise('Ejecuta una misma línea sin acentos añadidos y después con los signos escritos. Conserva las alturas y duraciones.'))
pg('agogica','8.3 · Tempo y agógica',P('El <b>tempo</b> establece la velocidad de referencia. La <b>agógica</b> comprende modificaciones expresivas del transcurso temporal. Ritardando (rit.) y rallentando (rall.) indican ralentización; accelerando (accel.), aceleración gradual. Sus diferencias de carácter dependen del contexto. [6]'),SC(dict(title='Ritardando: reducción gradual de velocidad',events=[N('C4',4,mark='rit.'),N('D4',4),N('E4',4),N('C4',4)]),dict(title='Accelerando: aumento gradual de velocidad',events=[N('C4',4,mark='accel.'),N('D4',4),N('E4',4),N('G4',4)]),dict(title='Restablecimiento del tempo',events=[N('G4',4,mark='a tempo'),N('E4',4),N('D4',4),N('C4',4)])),P('<b>A tempo</b> recupera la velocidad de referencia tras una modificación. <b>Tempo primo</b> restablece el tempo inicial. Largo, adagio, andante, moderato, allegro y presto orientan velocidad y carácter; no tienen límites universales de BPM. El rubato implica flexibilidad expresiva del tiempo.'))
pg('articulacion','8.4 · Legato, staccato y portato',P('La <b>articulación</b> organiza la unión o separación de los sonidos. <b>Legato</b> pide continuidad entre notas; <b>staccato</b>, separación mediante una reducción contextual de la duración sonora, sin alterar el valor métrico. El término español picado suele corresponder a staccato.'),SC(dict(title='Legato: arco sobre o bajo notas de distinta altura',events=[N(n,4) for n in ['C4','D4','E4','F4']],slurs=[[0,3]]),dict(title='Staccato: puntos',events=[N(n,4,mark='staccato') for n in ['C4','D4','E4','F4']]),dict(title='Portato: puntos dentro de una ligadura',events=[N(n,4,mark='staccato') for n in ['C4','D4','E4','F4']],slurs=[[0,3]])),P('<b>Portato</b> combina una conexión de frase con una ligera separación entre notas. <b>Tenuto</b> se representa mediante una raya y pide sostener el sonido, con el matiz de apoyo que requiera el contexto. Un punto de articulación no es un puntillo de duración. [7]'))
pg('fraseo','8.5 · Fraseo, respiración y suspensión',P('El <b>fraseo</b> organiza el discurso musical en unidades con dirección y continuidad. Una ligadura de fraseo puede reunir varios sonidos; no suma sus duraciones. La ligadura de prolongación, en cambio, une dos notas de igual altura sin nuevo ataque.'),SC(dict(title='Frase de cuatro notas',events=[N(n,4) for n in ['C4','D4','E4','C4']],slurs=[[0,3]]),dict(title='Tenuto y calderón',events=[N('G4',2,mark='tenuto'),N('C4',2,mark='fermata')]),dict(title='Respiración y cesura: indicaciones sobre el pentagrama',events=[N('C4',4),N('D4',4,mark=','),N('E4',4),N('C4',4,mark='//')])),P('El <b>calderón</b> prolonga expresivamente una nota o un silencio; no tiene un multiplicador fijo. La <b>coma de respiración</b> señala una articulación o toma de aire; la <b>cesura</b>, una interrupción más marcada. La duración concreta depende del contexto y de la dirección musical.'))
pg('adornos','8.6 · Ornamentos',P('Los <b>ornamentos</b> añaden sonidos o movimientos alrededor de una nota principal. Su ejecución depende de la época, el estilo, el tempo y las indicaciones de la edición. No todos admiten una única realización universal.'),SC(dict(title='Trino: alternancia con la nota superior',events=[N('G4',2,mark='tr'),N('G4',2)]),dict(title='Grupeto: recorrido alrededor de la nota principal',events=[N('G4',2,mark='turn'),N('G4',2)]),dict(title='Mordente: movimiento breve con la nota vecina',events=[N('G4',2,mark='mordent'),N('G4',2)])),P('Un grupeto puede recorrer superior-principal-inferior-principal. Los mordentes tienen variantes gráficas y convenciones históricas. Las apoyaturas se escriben como notas pequeñas y reciben parte del valor de la nota a la que se apoyan; las notas pequeñas atravesadas por un trazo suelen indicar una ornamentación breve.'),*exercise('Identifica qué signo solicita repetición alternada y cuál rodea la nota principal. Antes de ejecutar un adorno, verifica su realización en el contexto de la obra.'))
SEC='Módulo 9 · Repetición, recorrido y abreviaturas'
pg('barras','9.1 · Barras y signos de repetición',P('La <b>barra simple</b> separa compases. La <b>doble barra</b>, formada por dos trazos finos, delimita una sección o un cambio relevante. La <b>barra final</b> combina un trazo fino y otro grueso. Los dos puntos junto a la barra indican repetición.'),D('navigation',155,mode='bars'),P('La repetición final devuelve al signo de apertura; si no lo hay, al comienzo. Las <b>casillas de primera y segunda vez</b> ofrecen finales alternativos.'),D('navigation',155,mode='endings'),P('Recorrido del segundo ejemplo: <b>1-2-3 / 1-2-4</b>. En la segunda pasada se omite la primera casilla y se continúa por la segunda.'),*exercise('Traza el recorrido con el dedo antes de ejecutar. Explica por qué las dos casillas no se leen seguidas en la misma pasada.'))
pg('saltos','9.2 · Da capo, dal segno, Fine y Coda',P('<b>D.C. (da capo)</b> devuelve al principio. <b>D.S. (dal segno)</b> devuelve al segno. <b>Fine</b> indica el final en el recorrido señalado. La <b>coda</b> es una sección conclusiva a la que se accede por un salto indicado; su símbolo es un círculo cruzado. El segno y la coda son signos diferentes.'),D('navigation',145,mode='DSFine'),P('En el ejemplo, el segno está en el compás 1 y Fine, al terminar el 2. La orden al terminar el 4 produce el recorrido <b>1-2-3-4 / 1-2 y fin</b>.'),D('navigation',145,mode='DCCoda'),P('En el segundo esquema, toca 1-2-3; D.C. al Coda devuelve al comienzo. En la repetición, la indicación a Coda al terminar el 2 lleva al compás 4: <b>1-2-3 / 1-2 / 4</b>.'),S('D.C. al Fine: inicio y final en Fine. D.S. al Coda: segno y salto a coda. No se confunden «volver al inicio» y «volver al signo».'))
pg('tremolo','9.3 · Repetición abreviada y trémolo',P('Los trazos oblicuos sobre la plica pueden abreviar repeticiones. En los ejemplos <b>medidos</b>, una negra con un trazo equivale a dos corcheas; con dos, a cuatro semicorcheas; con tres, a ocho fusas. El conjunto ocupa siempre la duración de la negra escrita.'),SC(dict(title='Un trazo / dos corcheas',events=[N('G4',4,slashes=1)]+[N('G4',8) for _ in range(2)]),dict(title='Dos trazos / cuatro semicorcheas',events=[N('G4',4,slashes=2)]+[N('G4',16) for _ in range(4)]),dict(title='Tres trazos / ocho fusas',events=[N('G4',4,slashes=3)]+[N('G4',32) for _ in range(8)])),P('El <b>trémolo</b> consiste en una reiteración rápida; puede ser medido o no medido. En el no medido, los trazos indican rapidez y continuidad sin fijar un número exacto de ataques. El tempo, las indicaciones y la convención instrumental determinan la lectura. [8]'))
pg('redoble','9.4 · Redoble y duración escrita',P('El <b>redoble</b> sostiene una sonoridad mediante golpes sucesivos. Su notación debe distinguir una subdivisión medida de una reiteración no medida. Los trazos de abreviación no indican por sí solos qué mano toca ni si cada golpe es simple, doble o de rebote múltiple.'),SC(dict(title='Repetición medida: cuatro semicorcheas por negra',meter='2/4',bars=[[N('G4',4,slashes=2),N('G4',4,slashes=2)]]),dict(title='La misma duración, desarrollada',meter='2/4',bars=[[N('G4',16) for _ in range(8)]]),dict(title='Trémolo no medido: la indicación aclara el sentido',events=[N('G4',2,slashes=3,mark='no medido')],slurs=[])),P('Cuando una figura ya tiene corchetes o barras, estos cuentan en el nivel total de subdivisión de la abreviatura medida. En una partitura, consulta además la leyenda si se utiliza una notación especial de redoble.'),*exercise('Desarrolla una blanca con dos trazos como repetición medida. Respuesta: ocho semicorcheas, con duración total de dos negras.'))
SEC='Módulo 10 · Claves y lectura en dos pentagramas'
pg('fa','10.1 · Clave de Fa en cuarta línea',P('La clave de Fa sitúa fa3 en la cuarta línea; sus dos puntos quedan a ambos lados de esa línea. Permite escribir registros graves con menos líneas adicionales. La clave cambia el nombre de las posiciones, no el valor de las figuras.'),SC(row('Líneas: Sol-Si-Re-Fa-La',['G2','B2','D3','F3','A3'],1,clef='F'),row('Espacios: La-Do-Mi-Sol',['A2','C3','E3','G3'],1,clef='F'),row('Do mayor en clave de Fa',['C3','D3','E3','F3','G3','A3','B3','C4'],1,clef='F')),*exercise('Nombra las notas sin trasladar mentalmente las posiciones de Sol. Localiza fa3 y do4 como referencias. Escribe do3-mi3-sol3-do4.'))
pg('do','10.2 · Claves de Do',P('La clave de Do fija el <b>do4</b> en la línea central del signo. En tercera línea se denomina clave de alto; en cuarta, clave de tenor. La clave de alto es habitual en la viola. La clave de tenor aparece en registros agudos de instrumentos graves.'),SC(row('Do en tercera línea: escala de Do mayor',C,1,clef='C'),row('Do en cuarta línea: la misma escala',C,1,clef='T')),P('Las claves de Sol, Fa y Do han tenido otras posiciones históricas. En la lectura actual, las posiciones aquí estudiadas cubren usos frecuentes. Una clave no determina una tonalidad: esa función pertenece al contexto tonal y a la armadura.'),*exercise('1. Señala do4 en cada pentagrama.<br/>2. Escribe do4-mi4-sol4-do5 en ambas claves.<br/>3. Explica qué cambia gráficamente y qué permanece igual al cambiar de clave.'))
pg('teclado','10.3 · Registro y do central',P('El teclado de 88 teclas abarca de la0 a do8: 52 teclas blancas y 36 negras. Los grupos de dos y tres teclas negras permiten localizar los nombres. Do está inmediatamente a la izquierda de cada grupo de dos.'),D('keyboard',355),P('En este manual, <b>do4</b> es el do central. Los números de octava aumentan al pasar de si a do. Algunas aplicaciones utilizan otra numeración: confirma la convención al intercambiar datos.'),S('Estos pentagramas son mapas independientes de alturas. El sistema simultáneo se presenta en la página siguiente.'))
pg('sistema','10.4 · Sistema de dos pentagramas',P('El <b>sistema de dos pentagramas</b> reúne normalmente clave de Sol arriba y clave de Fa abajo. Una <b>llave</b> a la izquierda y una barra inicial los unen. Las notas situadas verticalmente en el mismo punto comienzan juntas. Las líneas divisorias coordinan los compases.'),D('grand',215,upper=['C4','E4','G4','C5'],lower=['C3','E3','G3','C4'],dur=1,bars=True,meter=True),P('El do central se escribe en la primera línea adicional inferior de Sol o en la primera adicional superior de Fa. Ambas escrituras representan el mismo sonido. No existe una frontera obligatoria que impida a un pentagrama entrar en el registro del otro.'),D('grand',195,upper=['C4'],lower=['C4'],dur=1),S('Cada par vertical del primer ejemplo dura un compás de 4/4. La llave reúne los pentagramas; no crea dos compases de distinta especie.'))
pg('dos-voces','10.5 · Lectura simultánea y ejercicio final',P('Lee cada pentagrama por separado. Identifica después las entradas simultáneas y conserva una sola referencia de pulso. El ejemplo siguiente contiene cuatro compases de 4/4; cada nota es una redonda.'),D('grand',215,upper=['E4','F4','D4','C4'],lower=['C3','F2','G2','C3'],dur=1,bars=True,meter=True),H('Ejercicios de integración'),P('1. Nombra las notas de cada voz y marca las cuatro pulsaciones de cada compás.<br/>2. Entona la voz superior mientras escuchas o ejecutas la inferior como referencia.<br/>3. Escribe las dos primeras notas de cada pentagrama una octava más aguda.<br/>4. Añade una dinámica inicial y una ligadura de fraseo; explica qué cambia y qué permanece igual.<br/>5. Sustituye cada redonda superior por dos blancas de la misma altura. Conserva la voz inferior.'),H('Comprobación'),P('Verifica nombres y octavas, duración de cada compás, alineación de entradas y significado de los signos añadidos. En la entonación, comprueba la afinación por separado de la precisión rítmica.'))
SEC='Apéndice · Comprobación y referencias'
pg('respuestas','Respuestas y criterios de comprobación',H('Elementos y compás'),P('1.1: desde fa, fa-sol-la-si-do-re-mi-fa. Re = D; sol = G; la = A; si = B.<br/>1.3: una blanca equivale a cuatro corcheas; una negra, a dieciséis semifusas; media redonda puede escribirse como dos negras.<br/>2.2: cada compás suma cuatro negras. Ocho corcheas equivalen a cuatro negras.<br/>2.9: una negra; silencio de negra; dos negras; dos negras.'),H('Intervalos y tonalidad'),P('Do-fa sostenido es cuarta aumentada; do-sol bemol, quinta disminuida. Ambos abarcan seis semitonos en temperamento igual.<br/>Do mayor tiene semitonos entre III-IV y VII-I.<br/>Un bemol: Fa mayor/Re menor; dos: Si bemol mayor/Sol menor; tres: Mi bemol mayor/Do menor.<br/>La menor armónica altera sol; la melódica ascendente, fa y sol. En el descenso clásico vuelven fa y sol naturales.'),H('Lectura integrada'),P('7.2, primera línea trasladada a Do mayor: do-re-mi / fa-mi-re / si-do, conservando los valores originales.<br/>10.5, voz superior: mi4-fa4-re4-do4. Inferior: do3-fa2-sol2-do3. Una octava más aguda: mi5-fa5 y do4-fa3 para las dos primeras notas.'),H('Verificación de ejercicios abiertos'),P('En una respuesta de composición o escritura puede haber varias soluciones correctas. Comprueba la capacidad del compás, las alteraciones de la armadura, la dirección interválica solicitada y la correspondencia entre signos y ejecución.'))
refs=[('1','RAE-ASALE. Diccionario de la lengua española: solfeo, solfear, leer y notación.','https://dle.rae.es/solfeo'),('2','Treccani. Guido Monaco d’Arezzo; Guido d’Arezzo e la nuova pedagogia musicale.','https://www.treccani.it/enciclopedia/guido-monaco-d-arezzo/'),('3','OnMusic Dictionary. Meters; Simple meter; Compound meter.','https://dictionary.onmusic.org/appendix/topics/meters'),('4','OnMusic Dictionary. Melodic minor scale.','https://dictionary.onmusic.org/terms/2133-melodic_minor_scale'),('5','OnMusic Dictionary. Dynamics; Sforzando.','https://dictionary.onmusic.org/terms/1259-dynamics'),('6','Treccani, Vocabolario: Agogica; Gran Enciclopèdia de la Música: Agògica.','https://www.enciclopedia.cat/gran-enciclopedia-de-la-musica/agogica'),('7','Store norske leksikon. Portato, musikk.','https://snl.no/portato_-_musikk'),('8','OnMusic Dictionary. Tremolo.','https://dictionary.onmusic.org/terms/3663-tremolo')]
pg('fuentes','Referencias de consulta',*[S(f'[{a}] {b}<br/><link href="{u}" color="#265b4d">{u}</link>') for a,b,u in refs],H('Materiales pedagógicos de referencia'),S('Tiero Pezzuti. Método teórico-práctico de solfeo, Parte I, Ediciones Petier. Ejemplar aportado: 1-solfeo_Teorico_APLICADO.pdf.'),S('Segundo manual aportado: 2_Solfeo_Aplicado2pdf.pdf, fragmento de 70 páginas. Se consultaron su secuencia de lectura y sus ejercicios de intervalos con preparación; no se atribuye autoría sin una portada bibliográfica verificable.'),S('Textos, ejercicios y organización de esta edición: Latin Music Mastery. Referencias consultadas para conceptos y progresión, sin reproducción de ejercicios de los manuales. Tipografía musical: Bravura, SIL Open Font License. Edición local de trabajo 0.2, octubre de 2026.'))
