pages.insert(navindex,dict(id='saltos-2',title='9.3 · Recorridos con Fine y Coda',section='Módulo 9 · Repetición, recorrido y abreviaturas',blocks=[P('La indicación completa combina un punto de regreso y una condición de final. Lee la orden entera antes de ejecutar el salto.'),D('navigation',150,mode='DCFine'),P('<b>D.C. al Fine:</b> toca los cuatro compases, regresa al comienzo y termina en Fine, al cerrar el compás 2. Recorrido: 1-2-3-4 / 1-2.'),D('navigation',150,mode='DSCoda'),P('<b>D.S. al Coda:</b> toca 1-2-3; regresa al segno del compás 1. En la nueva pasada, al cerrar el compás 2, salta a la coda del compás 4. Recorrido: 1-2-3 / 1-2 / 4.'),P('Los nombres descriptivos como «cruz» o «bola» no sustituyen la identificación del símbolo: distingue siempre segno y coda por su forma y su función.')]))
