# Final editorial refinements and explicit grouping of beamed figures.
for page in pages:
    if page['id']=='irregulares-0':page['title']='4.6 · Dosillo, tresillo y cuatrosillo'
    if page['id']=='irregulares-1':page['title']='4.7 · Quintillo, seisillo y septillo'
    if page['id']=='irregulares-2':page['title']='4.8 · Octosillo y novesillo'
    for block in page.get('blocks',[]):
        if block.get('kind')!='score':continue
        for r in block['rows']:
            if r.get('title','').startswith('Ligadura:'):
                r['ties']=r.pop('slurs')
            # Transpose only very high dominant arpeggios to a readable register.
            if 'V7' in r.get('title','') and 'primeras' not in r.get('title',''):
                if max(midi(e['pitch']) for e in r['events'])>81:
                    for e in r['events']:e['pitch']=e['pitch'][:-1]+str(int(e['pitch'][-1])-1)
            groups=[];ix=0
            for bar in r.get('bars',[]):
                onset=0;run=[];prior=None
                meter=r.get('meter','4/4');a0,b0=map(int,meter.split('/'));unit=1.5 if b0==8 and a0 in (6,9,12) else 4/b0
                for e in bar:
                    beat=int((onset+1e-7)/unit)
                    if not e.get('rest') and e['dur']>=8:
                        if prior==beat:run.append(ix)
                        else:
                            if len(run)>1:groups.append(run)
                            run=[ix]
                        prior=beat
                    else:
                        if len(run)>1:groups.append(run)
                        run=[];prior=None
                    onset+=4/e['dur']*(1.5 if e.get('dot') else 1);ix+=1
                if len(run)>1:groups.append(run)
            if r.get('tuplet'):groups=[list(range(len(r['events'])))]
            if groups:r['beams']=groups
